={{ JSON.stringify({ query: "mutation GroupType($type: String!) {
  metaobjectDefinitionCreate(definition: {
    type: $type, name: "Product group", displayNameKey: "name",
    description: "Separate products shown as one family, such as a cable in several lengths and colours.",
    access: { storefront: PUBLIC_READ },
    fieldDefinitions: [
      { key: "name", name: "Name", type: "single_line_text_field", required: true }
      { key: "group_options", name: "Options", type: "list.single_line_text_field",
        description: "The options in row order, such as Length then Colour." }
      { key: "products", name: "Products", type: "list.product_reference",
        description: "The members in value order. Liquid reads at most 50." }
      { key: "members_json", name: "Members", type: "json",
        description: "Every member with its option values and stock. Written by n8n; the theme reads this first." }
      { key: "managed", name: "Kept by n8n", type: "boolean",
        description: "On for groups the template made. It never changes or deletes a group with this off." }
    ]
  }) { metaobjectDefinition { id } userErrors { field message code } }
}", variables: { type: $('Setup settings').first().json.group_type } }) }}

={{ JSON.stringify({ query: "mutation Fields($ns: String!, $def: String!) {
  group: metafieldDefinitionCreate(definition: {
    name: "Product group", namespace: $ns, key: "product_group", ownerType: PRODUCT,
    type: "metaobject_reference", pin: true,
    validations: [{ name: "metaobject_definition_id", value: $def }],
    description: "The family this product belongs to."
  }) { createdDefinition { id } userErrors { field message code } }
  values: metafieldDefinitionCreate(definition: {
    name: "Option values", namespace: $ns, key: "option_values", ownerType: PRODUCT,
    type: "json", pin: true,
    description: "This product's value for each of its group's options, such as {\"Length\": \"2m\", \"Colour\": \"Blue\"}."
  }) { createdDefinition { id } userErrors { field message code } }
}", variables: { ns: $('Setup settings').first().json.namespace, def: $json.data.metaobjectDefinitionByType.id } }) }}

