// One line per thing Setup makes: created, or already there.
const said = (errs, made) => made ? 'created' : (errs || []).some(e => e.code === 'TAKEN' || /taken|already/i.test(e.message))
  ? 'already there' : 'failed: ' + (errs || []).map(e => e.message).join('; ');
const t = $('Create the group type').first().json.data.metaobjectDefinitionCreate;
const f = $json.data;
return [{ json: {
  product_group_type: said(t.userErrors, t.metaobjectDefinition),
  product_group_field: said(f.group.userErrors, f.group.createdDefinition),
  option_values_field: said(f.values.userErrors, f.values.createdDefinition),
} }];

