={{ JSON.stringify({ query: "query Products($after: String, $ns: String!) {
  products(first: 100, after: $after, query: "status:active AND published_status:published") {
    pageInfo { hasNextPage endCursor }
    nodes {
      id handle title vendor productType
      variants(first: 20) { nodes { sku availableForSale } }
      colour: metafield(namespace: "shopify", key: "color-pattern") {
        references(first: 1) { nodes { ... on Metaobject {
          label: field(key: "label") { value } color: field(key: "color") { value } } } }
      }
      group: metafield(namespace: $ns, key: "product_group") { value }
      values: metafield(namespace: $ns, key: "option_values") { value }
    }
  }
}", variables: { ns: $('Group settings').first().json.namespace } }) }}

={{ JSON.stringify({ query: "query Groups($after: String, $type: String!) {
  metaobjects(type: $type, first: 100, after: $after) {
    pageInfo { hasNextPage endCursor }
    nodes {
      id handle
      name: field(key: "name") { value }
      options: field(key: "group_options") { value }
      products: field(key: "products") { value }
      members: field(key: "members_json") { value }
      managed: field(key: "managed") { value }
    }
  }
}", variables: { type: $('Group settings').first().json.group_type } }) }}

