// Find each series: same vendor and type, same title once the option values and the SKU are taken out.
// Then compare with what Shopify holds and output one item per change.
const s = $('Group settings').first().json;
const products = $('Read products').all().flatMap(i => i.json.data.products.nodes);
const groups = $('Read groups').all().flatMap(i => i.json.data.metaobjects.nodes);
const overrides = Object.fromEntries($('Read overrides').all().map(i => i.json).filter(o => o.handle).map(o => [o.handle.trim(), o]));

const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const cap = w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
const tidy = t => t.replace(/\s+/g, ' ').replace(/\s+([,)\]])/g, '$1').replace(/^[\s,\-|/]+|[\s,\-|/]+$/g, '').trim();
const num = v => v.replace(/\s+/g, '').replace(/^\d+(?:\.\d+)?/, n => String(parseFloat(n)));
const slug = t => t.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 120);
const canon = v => JSON.stringify(v, (k, x) => x && typeof x === 'object' && !Array.isArray(x)
  ? Object.fromEntries(Object.keys(x).sort().map(key => [key, x[key]])) : x);
const parse = v => { try { return v == null ? null : JSON.parse(v); } catch (e) { return v; } };

// Read one product: its option values, its swatch colour and the title with both taken out.
function read(p) {
  let title = ' ' + p.title + ' ';
  if (s.strip_sku) {
    const skus = p.variants.nodes.map(v => (v.sku || '').trim()).filter(Boolean).sort((a, b) => b.length - a.length);
    for (const sku of skus) title = title.replace(new RegExp('(^|[\\s(\\[,])' + esc(sku) + '(?=$|[\\s)\\],])', 'gi'), '$1 ');
  }
  const values = {};
  let swatch = null;
  for (const o of s.options) {
    let v = null;
    const ref = o.colour_attribute && p.colour && p.colour.references.nodes[0];
    if (ref && ref.label) { v = ref.label.value; swatch = ref.color ? ref.color.value : null; }
    if (o.words) {
      const re = new RegExp('\\b(' + o.words.map(esc).join('|') + ')\\b', 'gi');
      const found = title.match(re);
      if (found && !v) v = cap(found[0]);
      title = title.replace(re, ' ');
    }
    if (o.pattern) {
      const found = title.match(new RegExp(o.pattern, 'gi')) || [];
      if (found.length === 1) { if (!v) v = num(found[0]); title = title.replace(new RegExp(o.pattern, 'gi'), ' '); }
    }
    if (v) values[o.name] = (o.aliases || {})[v] || v;
  }
  return { core: tidy(title), values, swatch };
}

// Groups you made by hand (Kept by n8n off) are left alone, and so are their products.
const byId = Object.fromEntries(groups.map(g => [g.id, g]));
const isManaged = g => g && g.managed && g.managed.value === 'true';
const field = (p, k) => p[k] && p[k].value;

const series = {}, forced = [];
for (const p of products) {
  const current = byId[field(p, 'group')];
  if (current && !isManaged(current)) continue;
  const o = overrides[p.handle];
  if (o && String(o.group_name).trim().toLowerCase() === 'exclude') continue;
  const r = read(p);
  if (o && o.group_name) {
    if (o.option_values) Object.assign(r.values, parse(o.option_values) || {});
    forced.push({ name: o.group_name.trim(), m: { p, ...r } });
    continue;
  }
  const parts = { vendor: p.vendor, product_type: p.productType };
  const key = s.match_on.map(m => (parts[m] || '').toLowerCase()).concat(r.core.toLowerCase()).join('|');
  (series[key] = series[key] || { key, name: r.core, members: [] }).members.push({ p, ...r });
}
// An override joins the series with that name, or starts one.
for (const f of forced) {
  const g = Object.values(series).find(x => x.name.toLowerCase() === f.name.toLowerCase());
  const key = g ? g.key : 'override|' + f.name.toLowerCase();
  (series[key] = series[key] || { key, name: f.name, members: [] }).members.push(f.m);
}

const order = (a, b) => {
  const x = parseFloat(a), y = parseFloat(b);
  return !isNaN(x) && !isNaN(y) && x !== y ? x - y : String(a).localeCompare(String(b));
};
const want = {}, wantMember = {}, report = [];
// Handle: the series name, plus the product type when two series share a name.
const nameCount = {};
for (const g of Object.values(series)) nameCount[slug(g.name)] = (nameCount[slug(g.name)] || 0) + 1;
for (const g of Object.values(series)) {
  if (g.members.length < s.min_members) continue;
  // An option counts when the group has two or more values for it.
  const options = s.options.map(o => o.name).filter(n => new Set(g.members.map(m => m.values[n]).filter(Boolean)).size > 1);
  if (!options.length) continue;
  const complete = [], seen = {};
  for (const m of g.members.sort((a, b) => a.p.handle.localeCompare(b.p.handle))) {
    const missing = options.filter(n => !m.values[n]);
    if (missing.length) { report.push({ action: 'near_miss', group_name: g.name, product: m.p.handle, detail: 'no ' + missing.join(' or ') }); continue; }
    const combo = options.map(n => m.values[n]).join(' / ');
    if (seen[combo]) { report.push({ action: 'duplicate', group_name: g.name, product: m.p.handle, detail: combo + ' is already ' + seen[combo] }); continue; }
    seen[combo] = m.p.handle; complete.push(m);
  }
  if (complete.length < s.min_members) continue;
  complete.sort((a, b) => { for (const n of options) { const c = order(a.values[n], b.values[n]); if (c) return c; } return 0; });
  const handle = nameCount[slug(g.name)] > 1 ? slug(g.key) : slug(g.name);
  const members_json = complete.map(m => {
    const values = Object.fromEntries(options.map(n => [n, m.values[n]]));
    const row = { handle: m.p.handle, values, available: m.p.variants.nodes.some(v => v.availableForSale) };
    if (m.swatch && options.some(n => s.options.find(o => o.name === n).colour_attribute)) row.swatch = m.swatch;
    return row;
  });
  want[handle] = { handle, name: g.name, options, products: complete.slice(0, 50).map(m => m.p.id), members_json };
  for (const m of complete) wantMember[m.p.id] = { handle, values: Object.fromEntries(options.map(n => [n, m.values[n]])), product: m.p.handle };
}

// Compare with Shopify.
const managed = groups.filter(isManaged);
const byHandle = Object.fromEntries(managed.map(g => [g.handle, g]));
const out = [];
for (const w of Object.values(want)) {
  const g = byHandle[w.handle];
  const same = g && field(g, 'name') === w.name && canon(parse(field(g, 'options'))) === canon(w.options)
    && canon(parse(field(g, 'products'))) === canon(w.products) && canon(parse(field(g, 'members'))) === canon(w.members_json);
  if (!same) out.push({ action: 'group_set', group_name: w.name, handle: w.handle, metaobject_id: g ? g.id : null,
    options: w.options, products: w.products, members_json: w.members_json,
    detail: (g ? 'update: ' : 'new: ') + w.options.join(' × ') + ', ' + w.members_json.length + ' products' });
}
for (const g of managed) if (!want[g.handle]) out.push({ action: 'group_delete', group_name: field(g, 'name'), handle: g.handle, metaobject_id: g.id, detail: 'no series left' });
for (const p of products) {
  const w = wantMember[p.id], cur = byId[field(p, 'group')];
  if (cur && !isManaged(cur)) continue;
  if (w) {
    const same = cur && cur.handle === w.handle && canon(parse(field(p, 'values'))) === canon(w.values);
    if (!same) out.push({ action: 'member_set', group_name: want[w.handle].name, handle: w.handle, product_id: p.id, product: p.handle,
      option_values: w.values, detail: Object.values(w.values).join(' / ') });
  } else if (field(p, 'group') || field(p, 'values')) {
    out.push({ action: 'member_clear', group_name: cur ? field(cur, 'name') : '', product_id: p.id, product: p.handle, detail: 'left its series' });
  }
}
return out.concat(report).map(json => ({ json }));

// Write the changes in order: groups first (products point at them), then product links, then deletes.
// Why Code: products need the new group IDs, metafieldsSet takes 25 fields a call, and Shopify throttles.
const s = $('Group settings').first().json;
const token = $('Get Shopify token for Group').first().json.access_token;
const url = 'https://' + s.store_domain + '/admin/api/2026-10/graphql.json';
const items = $input.all().map(i => i.json);
const sleep = ms => new Promise(r => setTimeout(r, ms));
const gql = async (query, variables) => {
  for (let a = 0; a < 5; a++) {
    const r = await this.helpers.httpRequest({ method: 'POST', url, json: true, body: { query, variables },
      headers: { 'X-Shopify-Access-Token': token } });
    if ((r.errors || []).some(e => (e.extensions || {}).code === 'THROTTLED')) { await sleep(2000 * (a + 1)); continue; }
    return r;
  }
  throw new Error('Shopify throttled five times in a row');
};
const problem = (r, k) => (r.errors || []).map(e => e.message)
  .concat(((r.data || {})[k] || {}).userErrors ? r.data[k].userErrors.map(e => e.message) : []).join('; ');
const mark = (x, err) => { x.status = err ? 'failed: ' + err.slice(0, 200) : (s.dry_run ? 'dry run' : 'written'); };
const by = a => items.filter(x => x.action === a);
if (s.dry_run) { items.forEach(x => { if (!['near_miss', 'duplicate'].includes(x.action)) mark(x); }); return items.map(json => ({ json })); }

const ids = {};
for (const g of by('group_set')) {
  const r = await gql(`mutation($h: MetaobjectHandleInput!, $m: MetaobjectUpsertInput!) {
    metaobjectUpsert(handle: $h, metaobject: $m) { metaobject { id } userErrors { field message } } }`, {
    h: { type: s.group_type, handle: g.handle },
    m: { fields: [
      { key: 'name', value: g.group_name },
      { key: 'group_options', value: JSON.stringify(g.options) },
      { key: 'products', value: JSON.stringify(g.products) },
      { key: 'members_json', value: JSON.stringify(g.members_json) },
      { key: 'managed', value: 'true' },
    ] } });
  const id = r.data && r.data.metaobjectUpsert && r.data.metaobjectUpsert.metaobject && r.data.metaobjectUpsert.metaobject.id;
  if (id) ids[g.handle] = id;
  mark(g, id ? '' : problem(r, 'metaobjectUpsert') || 'no id returned');
}
const known = Object.fromEntries($('Read groups').all().flatMap(i => i.json.data.metaobjects.nodes).map(g => [g.handle, g.id]));
const links = by('member_set');
links.forEach(m => { m.group_id = ids[m.handle] || known[m.handle]; if (!m.group_id) mark(m, 'its group was not written'); });
const ready = links.filter(m => m.group_id);
for (let i = 0; i < ready.length; i += 12) {
  const batch = ready.slice(i, i + 12);
  const metafields = batch.flatMap(m => [
    { ownerId: m.product_id, namespace: s.namespace, key: 'product_group', type: 'metaobject_reference', value: m.group_id },
    { ownerId: m.product_id, namespace: s.namespace, key: 'option_values', type: 'json', value: JSON.stringify(m.option_values) },
  ]);
  const r = await gql(`mutation($m: [MetafieldsSetInput!]!) { metafieldsSet(metafields: $m) { userErrors { field message } } }`, { m: metafields });
  batch.forEach(m => mark(m, problem(r, 'metafieldsSet')));
}
const leavers = by('member_clear');
for (let i = 0; i < leavers.length; i += 12) {
  const batch = leavers.slice(i, i + 12);
  const metafields = batch.flatMap(m => ['product_group', 'option_values'].map(key => ({ ownerId: m.product_id, namespace: s.namespace, key })));
  const r = await gql(`mutation($m: [MetafieldIdentifierInput!]!) { metafieldsDelete(metafields: $m) { userErrors { field message } } }`, { m: metafields });
  batch.forEach(m => mark(m, problem(r, 'metafieldsDelete')));
}
for (const g of by('group_delete')) {
  const r = await gql(`mutation($id: ID!) { metaobjectDelete(id: $id) { deletedId userErrors { field message } } }`, { id: g.metaobject_id });
  mark(g, problem(r, 'metaobjectDelete'));
}
return items.map(json => ({ json }));

// A Slack message when something changed, plus once a day (report_hour) for near misses and duplicates.
const s = $('Group settings').first().json;
const all = $input.all().map(i => i.json);
const changes = all.filter(x => ['group_set', 'group_delete', 'member_set', 'member_clear'].includes(x.action));
const failed = changes.filter(x => String(x.status).startsWith('failed'));
const daily = $now.hour === s.report_hour && all.some(x => ['near_miss', 'duplicate'].includes(x.action));
if (!changes.length && !daily) return [];
const n = a => changes.filter(x => x.action === a).length;
const w = s.dry_run ? ['Would write', 'delete', 'link', 'unlink'] : ['Wrote', 'deleted', 'linked', 'unlinked'];
const groupsSet = changes.filter(x => x.action === 'group_set');
const list = (label, xs, fmt) => xs.length ? '\n*' + label + '* (' + xs.length + '): ' + xs.slice(0, 10).map(fmt).join(', ') + (xs.length > 10 ? ', ...' : '') : '';
const text = ':link: Product groups' + (s.dry_run ? ' (dry run, nothing written)' : '') + '\n'
  + (!changes.length ? 'No changes this run.' : w[0] + ' ' + n('group_set') + (n('group_set') === 1 ? ' group, ' : ' groups, ') + w[1] + ' ' + n('group_delete') + ', ' + w[2] + ' ' + n('member_set') + ' products and ' + w[3] + ' ' + n('member_clear') + '.')
  + groupsSet.slice(0, 8).map(g => '\n• ' + g.group_name + ' (' + g.detail + ')').join('')
  + (groupsSet.length > 8 ? '\nand ' + (groupsSet.length - 8) + ' more.' : '')
  + list('Near misses, not grouped', all.filter(x => x.action === 'near_miss'), x => x.product + ' (' + x.detail + ')')
  + list('Duplicates, left out', all.filter(x => x.action === 'duplicate'), x => x.product + ' (' + x.detail + ')')
  + list('Failed', failed, x => (x.product || x.group_name) + ': ' + x.status.replace('failed: ', ''));
return [{ json: { channel: s.slack_channel, text, unfurl_links: false } }];
